cpu_set_t mask;
pid_t target_pid = 0; // Calling thread

// Initialize and define affinity
CPU_ZERO(&mask);
CPU_SET(0, &mask); // Allow running on CPU 0
CPU_SET(3, &mask); // Allow running on CPU 3

// Set the affinity mask
int status = sched_setaffinity(target_pid,
                               sizeof(cpu_set_t),
                               &mask);

if (status == -1) {
    // Handle error (e.g., lack of permissions)
}
